'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const themes={'aurora':'Aurora','nebula':'Nebula','amber':'Amber Terminal','ocean':'Deep Ocean','solar':'Solar Flare','lunar':'Lunar','forest':'Forest','retro':'Retro Console','lcars':'TNG LCARS','red-alert':'LCARS Red Alert','mission-control':'Mission Control','expanse':'The Expanse','minimal':'Minimal Mirror','blueprint':'Blueprint','warm-night':'Warm Night'};
const titles={yearprogress:'Year in orbit',daylight:'Daylight / Moonlight',mission:'Mission progress',commute:'Travel times',schoolcommute:'ETA to School',clock:'Local time',upnext:'Up next',weather:'Atmospheric conditions',agenda:'Schedule',assignments:'Assignment log',shipments:'Cargo manifest',countdowns:'On the horizon',notes:'Daily aerospace trivia',radar:'Weather radar',workshop:'Workshop log',connections:'Connection status',classes:'Class timetable',sensors:'Sensor telemetry'};
const pageWidgets={daily:['radar','workshop','connections','classes','sensors','yearprogress','mission','schoolcommute','daylight','commute','clock','weather','agenda','assignments','upnext','shipments','countdowns','notes'],school:['clock','upnext','assignments','classes','countdowns','agenda'],workshop:['clock','workshop','shipments','sensors','countdowns','notes'],calendar:['agenda','weather','radar','connections','upnext']};
const pageTitles={daily:'Daily overview',school:'Academic operations',workshop:'Workshop operations',calendar:'Calendar & conditions'};
let token=new URLSearchParams(location.hash.slice(1)).get('token')||sessionStorage.getItem('mirror-token')||'';
if(token){sessionStorage.setItem('mirror-token',token);history.replaceState(null,'',location.pathname);}
let state=null,arranging=false,layoutDraft={},hiddenDraft=[],monthOffset=0,drag=null,settingsTab='Display',radarIndex=-1,radarPlaying=false,lastBlank=Date.now(),lastRotate=Date.now(),toastTimer,pollBusy=false;
let screenPage=null,editorHeight=0;
const radarImageCache=new Map();
let pollFlight=null,lastPollError="";const localErrors=[];
const fmt=(date,options={})=>new Intl.DateTimeFormat('en-US',{timeZone:state?.config.timezone||'America/Chicago',...options}).format(new Date(date));
const dateKey=date=>fmt(date,{year:'numeric',month:'2-digit',day:'2-digit'});
const timeText=date=>fmt(date,{hour:'numeric',minute:'2-digit',hour12:!state.config.hour24});
const now=()=>new Date();
function logError(source,message){message=String(message).replace(/https?:\/\/\S+/g,'[URL]');if(!localErrors.some(e=>e.source===source&&e.message===message)){localErrors.push({time:new Date().toISOString(),source,message});if(localErrors.length>30)localErrors.shift();}drawLog();}
function drawLog(){const box=$('#logLines');if(!box)return;const rows=[...(state?.error_log||[]),...localErrors].sort((a,b)=>Date.parse(b.time)-Date.parse(a.time)).slice(0,30);$('#logCount').textContent=String(rows.length).padStart(2,'0');box.innerHTML=rows.length?rows.map(e=>`<div class="ops-log-entry"><time>${esc(new Date(e.time).toLocaleTimeString())}</time><strong>${esc(e.source)}</strong> · ${esc(e.message)}</div>`).join(''):'No application errors.';}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:{'Authorization':'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok){const error=new Error(data.error||'Request failed');error.status=response.status;logError('Request',error.message);throw error;}return data;}
async function action(body){await api('/api/action',body);await poll(true);}
function empty(message){return `<div class="empty">${esc(message)}</div>`;}
function link(url,label){try{if(new URL(url).protocol!=='https:')return '';}catch{return '';}return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;}
function age(timestamp){if(!timestamp)return 'Never synced';const sec=Math.max(0,(Date.now()-Date.parse(timestamp))/1000);return sec<60?'Just now':sec<3600?Math.floor(sec/60)+'m ago':Math.floor(sec/3600)+'h ago';}
function remaining(target){const sec=(Date.parse(target)-Date.now())/1000;if(sec<=0)return 'Now / passed';if(sec>=86400)return Math.floor(sec/86400)+'d '+Math.floor(sec%86400/3600)+'h';if(sec>=3600)return Math.floor(sec/3600)+'h '+Math.floor(sec%3600/60)+'m';return Math.max(1,Math.ceil(sec/60))+' min';}
function relevantEvents(){return state.events.filter(e=>!e.assignment&&Date.parse(e.end)>Date.now()).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));}
function renderClock(){return `<div class="clock-time" id="clockTime"></div><div class="date" id="clockDate"></div><div class="clock-zone" id="clockZone"></div><div class="clock-year">${renderYearProgress()}</div>`;}
function renderUpnext(){const event=relevantEvents()[0];if(!event)return empty('Nothing scheduled. Add a calendar or class timetable in Settings.');const ongoing=Date.parse(event.start)<Date.now();return `<div class="eyebrow">${ongoing?'IN PROGRESS':esc(event.source)}</div><div class="upnext-title">${esc(event.title)}</div><div class="small muted">${esc(event.location||'No location set')}</div><div style="margin-top:16px" class="count-pill" data-countdown="${esc(ongoing?event.end:event.start)}" data-prefix="${ongoing?'Ends in ':'Starts in '}"></div>`;}
function weatherWarning(){const error=state.connections.weather?.error;return error?`<p class="small late">${esc(error)}${state.weather?' Showing previous data.':''}</p>`:'';}
function renderWeather(){const w=state.weather;if(!w)return weatherWarning()+empty('Set the shared US ZIP code in Settings → Weather. No API key needed.');const c=w.current,d=w.daily;const tempUnit=state.config.units==='fahrenheit'?'°F':'°C';const code=c.weather_code;const condition=code===0?'Clear sky':code<=2?'Partly cloudy':code===3?'Overcast':code>=95?'Thunderstorms':code>=71&&code<=77?'Snow':code>=51?'Rain / showers':'Fog';const solar=key=>{const t=d[key]?.[0];return t?new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',hour12:!state.config.hour24}).format(new Date(t)):'—';};return `${weatherWarning()}<div class="small muted">${esc(w.place)}</div><div class="weather-main"><span class="weather-icon">${code<=2?'☀':code===3?'☁':'☂'}</span><span class="weather-temp">${Math.round(c.temperature_2m)}${tempUnit}</span></div><div>${condition}</div><div class="weather-details"><span>Feels like <b>${Math.round(c.apparent_temperature)}°</b></span><span>High ${Math.round(d.temperature_2m_max[0])}° / Low ${Math.round(d.temperature_2m_min[0])}°</span><span>Wind ${esc(c.wind_speed_10m)} ${esc(w.current_units.wind_speed_10m)}</span><span>Humidity ${esc(c.relative_humidity_2m)}%</span></div><div class="solar"><span>↑ Sunrise ${solar('sunrise')}</span><span>↓ Sundown ${solar('sunset')}</span></div><div class="tiny muted" style="margin-top:11px">${esc(w.timezone)} · Open-Meteo / Zippopotam.us<br>Weather time ${esc(c.time.replace('T',' '))}</div>`;}
function omitUpNext(events,next,visible){if(!visible||!next)return events;return events.filter(e=>!(e.key===next.key&&Date.parse(e.start)===Date.parse(next.start)));}
function scheduleRows(){const hidden=arranging?hiddenDraft:state.config.hidden[screenPage]||[];const visible=!hidden.includes('upnext')&&Boolean(activeLayout().upnext);return omitUpNext(state.schedule_events||state.events||[],relevantEvents()[0],visible);}
function renderAgenda(){if(screenPage==='calendar')return renderCalendar();let html='',last='';const events=scheduleRows().filter(e=>state.config.schedule_all_day||!e.all_day).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));for(const e of events){const day=dateKey(e.start);if(last!==day){html+=`<div class="section-label">${day===dateKey(now())?'Today':esc(fmt(e.start,{weekday:'long',month:'short',day:'numeric'}))}</div>`;last=day;}html+=`<div class="event" style="--event:${/^#[0-9a-f]{6}$/i.test(e.color)?e.color:'#bbaaff'}"><div class="event-time">${e.all_day?'ALL DAY':esc(timeText(e.start))} · ${esc(e.source)}</div><div class="event-title">${esc(e.title)}</div><div class="event-location">${state.config.schedule_locations?esc(e.location||''):''}</div></div>`;}return html||empty('No events in this range. Adjust Settings → Calendars.');}
function renderAssignments(){const rows=state.assignments;if(!rows.length)return empty('Add a calendar and enable “Assignment checklist” to see due dates here.');let done=rows.filter(r=>r.done).length;let html=`<div class="progress-line"><span>${done} OF ${rows.length} COMPLETED</span><span>LOCAL CHECKLIST</span></div><div class="progress-track"><i style="width:${done/rows.length*100}%"></i></div>`;for(const [key,label] of Object.entries({overdue:'Overdue',today:'Due today',week:'Due this week',later:'Later',completed:'Completed'})){const group=rows.filter(r=>r.priority===key);if(!group.length)continue;html+=`<div class="task-group ${key==='overdue'?'late':''}">${label}</div>`;for(const row of group){html+=`<label class="task ${row.done?'done':''}"><input type="checkbox" data-task="${esc(row.key)}" ${row.done?'checked':''} aria-label="Complete ${esc(row.title)}"><span><span class="task-title">${esc(row.title)}</span><div class="due ${key==='overdue'?'late':''}">${esc(fmt(row.start,{month:'short',day:'numeric'}))} ${row.all_day?'':esc(timeText(row.start))} · ${esc(row.source)}</div></span></label>`;}}return html;}
function renderShipments(){let html='<div class="eyebrow" style="margin-bottom:16px">Email notices + manual orders</div>';for(const [key,c] of Object.entries(state.connections)){if((key==='email'||key.startsWith('email:'))&&c.error)html+=`<p class="small late">${esc(c.label)}: ${esc(c.error)}</p>`;}const stages=['Ordered','Shipped','Out for delivery','Delivered'];for(const item of [...state.shipments].sort((a,b)=>stages.indexOf(a.stage)-stages.indexOf(b.stage))){const n=stages.indexOf(item.stage);html+=`<div class="shipment"><div class="stage">${esc(item.carrier||'Order')} · ${esc(item.stage)}${item.assumed_delivered?' · Assumed':''}</div><div class="shipment-title">${esc(item.title)}</div><div class="small muted">${esc(item.eta||'No estimate in notice')}</div><div class="steps" aria-label="Stage ${n+1} of 4">${stages.map((_,i)=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div>${item.link?'<div class="tiny">'+link(item.link,'Open official tracking')+'</div>':''}${state.config.manual_shipments.some(x=>x.id===item.id)?`<button class="text-button" data-edit="manual_shipments" data-id="${esc(item.id)}">Update order</button>`:''}</div>`;}if(!state.shipments.length)html+=empty('No shipping notices yet. Connect an email folder or add an order manually.');return html+'<button class="add-button" data-add="manual_shipments">+ Add an order</button><div class="tiny muted" style="margin-top:10px">Status reflects notices, not live carrier tracking.</div>';}
function renderCountdowns(){let html=state.config.countdowns.map(item=>`<div class="countdown-row"><div><div>${esc(item.title)}</div><div class="tiny muted">${esc(item.category||'Personal')} · ${esc(fmt(item.target,{month:'short',day:'numeric'}))}</div></div><button class="text-button countdown-number" data-edit="countdowns" data-id="${esc(item.id)}" data-countdown="${esc(item.target)}"></button></div>`).join('');return (html||empty('Count down to exams, project deadlines, or launch day.'))+'<button class="add-button" data-add="countdowns">+ New countdown</button>';}
function renderWorkshop(){let html='';for(const kind of ['Task','Parts needed','Maintenance']){const rows=state.config.workshop.filter(t=>t.kind===kind);html+=`<div class="section-label">${kind}</div>`;for(const item of rows){html+=`<div class="task ${item.done?'done':''}"><input type="checkbox" data-workshop="${esc(item.id)}" ${item.done?'checked':''} aria-label="Complete ${esc(item.title)}"><div><div class="task-title">${esc(item.title)}</div><div class="due">${esc(item.detail||'')}${item.due?' · '+esc(fmt(item.due,{month:'short',day:'numeric'})):''}</div><button class="text-button" data-edit="workshop" data-id="${esc(item.id)}">Edit</button></div></div>`;}}return html+'<button class="add-button" data-add="workshop">+ Task, part or maintenance reminder</button>';}
function renderClasses(){const rows=state.class_events||[];let html=rows.map(e=>`<div class="event" style="--event:${esc(e.color)}"><div class="event-time">${esc(fmt(e.start,{weekday:'short',month:'short',day:'numeric'}))} · ${e.all_day?'All day':esc(timeText(e.start))+'–'+esc(timeText(e.end))}</div><div class="event-title">${esc(e.title)}</div><div class="event-location">${esc(e.location||'')} · ${esc(e.source)}</div></div>`).join('');return html||empty('Select a calendar using “Use for Class Times” in Settings → Calendars. No upcoming classes loaded.');}
function renderSensors(){return (state.sensors.length?`<div class="sensor-grid">${state.sensors.map(s=>`<div><div class="eyebrow">${esc(s.name)}</div><div class="sensor-value">${esc(s.value)}<span class="tiny"> ${esc(s.unit||'')}</span></div><div class="tiny muted">${age(s.updated)}</div></div>`).join('')}</div>`:empty('Optional: connect a local JSON file or send readings to the authenticated sensor endpoint. See the setup guide.'))+`<div class="tiny muted" style="margin-top:15px">${state.demo?'SIMULATED READINGS':'Display only • verify readings on your instruments.'}</div>`;}
function fanPercentLabel(data){const percent=data?.fan_percent??data?.control?.percent;if(Number.isFinite(percent))return percent+'%';if(data?.control?.mode==='error')return '—% (control error)';if(data?.control?.target_percent!==undefined)return 'Auto (target '+data.control.target_percent+'%)';return '—% (Auto)';}
function renderIdracFooter(){const node=$('#idracFooter');if(!node)return;node.hidden=!state.config.idrac_enabled;if(node.hidden)return;const data=state.idrac,c=state.connections.idrac;const stale=Boolean(c?.error||c?.stale);const fans=data?.fans||[],temps=data?.temperatures||[];node.textContent='kWh '+(data?.kwh??'—')+' · Fan '+fanPercentLabel(data)+' · Avg '+(data?.avg_fan_rpm!==undefined&&data?.avg_fan_rpm!==null?Math.round(data.avg_fan_rpm)+' RPM':'— RPM')+' · CPU '+(temps.length?temps.map(t=>t.celsius+'°C').join(' / '):'—');node.title=stale?'iDRAC disconnected: showing last readings':data?.control?.message||data?.warning||'iDRAC telemetry';node.classList.toggle('telemetry-stale',stale);}
function renderConnections(){const idrac=state.connections.idrac;const idracRow=`<div class="connection"><span><i class="dot ${idrac?.error?'error':!state.config.idrac_enabled||!idrac?.success?'pending':''}"></i>iDRAC</span><span>${!state.config.idrac_enabled?'Disabled':idrac?.error?'Disconnected':idrac?.success?'Connected · '+esc(state.idrac?.control?.mode||'monitoring')+' · '+esc(age(idrac.success)):'Waiting'}</span></div>${idrac?.error?'<div class="tiny late">'+esc(idrac.error)+'</div>':''}${state.idrac?.control?.message?'<div class="tiny muted">'+esc(state.idrac.control.message)+'</div>':''}`;const ip=`<div class="connection"><strong>Local IP</strong><span>${esc(state.local_ip||'Unavailable')}</span></div>`;return ip+idracRow+(Object.values(state.connections).filter(c=>c.label!=='iDRAC').map(c=>`<div class="connection"><span><i class="dot ${c.error?'error':c.stale?'pending':''}"></i>${esc(c.label)}</span><span class="muted">${c.sample?'Sample data':esc(age(c.success))}</span></div>${c.error?`<div class="tiny late" style="margin:-5px 0 12px">${esc(c.error)}</div>`:''}`).join('')||empty('No connections configured yet.'));}
function renderRadar(){const r=state.radar;if(!r)return empty(state.connections.radar?.error||'Enter a ZIP code and refresh to load recent precipitation radar.');if(radarIndex<0||radarIndex>=r.frames.length)radarIndex=r.frames.length-1;return `<div id="radarMap" class="radar-map ${r.demo?'radar-demo':''}"><i class="radar-marker"></i><span class="radar-caption">${r.demo?'SIMULATED RADAR · SAMPLE DATA':'Recent precipitation · ZIP location'}</span></div><div class="radar-controls"><button id="radarPlay">${radarPlaying?'Pause':'Play'}</button><input id="radarRange" aria-label="Radar frame" type="range" min="0" max="${r.frames.length-1}" value="${radarIndex}"><span id="radarTime" class="tiny"></span></div><div class="tiny muted" style="margin-top:8px">${link('https://www.rainviewer.com/','Weather data by RainViewer')} · ${link('https://www.openstreetmap.org/copyright','© OpenStreetMap contributors')} · ${link('https://radar.weather.gov/','Open official NWS radar')}<br>Past radar, not a forecast. ${state.connections.radar?.error?esc(state.connections.radar.error):''}</div>`;}
function radarDraw(){const r=state?.radar,map=$('#radarMap');if(!r||!map)return;const f=r.frames[radarIndex];$('#radarTime').textContent=timeText(f.time*1000);if(r.demo)return;$$('img',map).forEach(img=>img.remove());const z=6,n=2**z,xf=(r.longitude+180)/360*n,lat=r.latitude*Math.PI/180,yf=(1-Math.asinh(Math.tan(lat))/Math.PI)/2*n;for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){const x=Math.floor(xf)+dx,y=Math.floor(yf)+dy;for(const kind of ['base','radar']){const url=kind==='base'?`https://tile.openstreetmap.org/${z}/${x}/${y}.png`:`https://tilecache.rainviewer.com${f.path}/256/${z}/${x}/${y}/2/1_1.png`;let img=radarImageCache.get(url);if(!img){img=document.createElement('img');img.referrerPolicy='strict-origin-when-cross-origin';img.alt='';img.loading='eager';img.src=url;radarImageCache.set(url,img);if(radarImageCache.size>180)radarImageCache.delete(radarImageCache.keys().next().value);}img.style.left=(map.clientWidth/2+(x-xf)*256)+'px';img.style.top=(map.clientHeight/2+(y-yf)*256)+'px';img.style.zIndex=kind==='radar'?2:1;img.onerror=()=>{const label=$('.radar-caption',map);label.textContent='Map provider unavailable or blocked. Use official radar below.';};map.append(img);}}}
function renderCalendar(){const parts=fmt(now(),{year:'numeric',month:'numeric'}).split('/');const base=new Date(Number(parts[1]),Number(parts[0])-1+monthOffset,1);const month=base.getMonth(),year=base.getFullYear(),first=(base.getDay()+6)%7,total=new Date(year,month+1,0).getDate();let html=`<div class="calendar-toolbar"><button id="prevMonth" aria-label="Previous month">‹</button><h3>${esc(base.toLocaleDateString('en-US',{month:'long',year:'numeric'}))}</h3><button id="nextMonth" aria-label="Next month">›</button></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}`;for(let i=0;i<first;i++)html+='<div></div>';for(let day=1;day<=total;day++){const target=`${String(month+1).padStart(2,'0')}/${String(day).padStart(2,'0')}/${year}`;const events=(state.schedule_events||state.events||[]).filter(e=>dateKey(e.start)===target);html+=`<div class="calendar-day ${target===dateKey(now())?'today':''}"><span>${day}</span>${events.slice(0,3).map(e=>`<div class="mini-event" title="${esc(e.title)}">${esc(e.title)}</div>`).join('')}${events.length>3?`<div class="tiny">+${events.length-3} more</div>`:''}</div>`;}return html+'</div><p class="tiny muted">Shows loaded calendar range; extend “Days ahead” in Settings for later dates.</p>';}
function renderTrivia(){const t=state.trivia;let warning=state.connections.news?.error;let html=warning?`<p class="small late">${esc(warning)}</p>`:'';if(!t)return html+empty('Daily aerospace trivia will appear automatically after NASA news loads.');return html+`<div class="eyebrow">${esc(t.day)} · ${esc(t.source)} ${t.older?'· OLDER CACHED HEADLINE':''}</div><p style="font-size:19px;line-height:1.45;color:var(--a)">${esc(t.title)}</p><p class="small muted">${esc(t.question)} ${esc(t.masked)}</p><p class="small"><strong>Answer: ${esc(t.answer)}</strong></p><div class="tiny muted">Published ${esc(fmt(t.published,{month:'short',day:'numeric',year:'numeric'}))} · ${link(t.url,'Read the NASA update')}</div>`;}
function renderEta(name){const item=state.commutes?.[name];if(!state.config.routes_enabled)return empty('Configure live ETA in Settings → Commute.');if(!item)return empty('Waiting for route update…');return `<div class="eta-value">${item.error?'—':esc(item.minutes)+' min'}</div><div class="small muted">${item.error?esc(item.error):'Leave now · '+esc(age(item.updated))}</div><div class="tiny muted">Google Maps</div>`;}
function renderCommute(){const c=state.config;if(!c.commute_origin||!c.commute_destination)return empty('Enter your start and work addresses in Settings → Commute.');const url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(c.commute_origin)+'&destination='+encodeURIComponent(c.commute_destination)+'&travelmode=driving';return `<div class="eyebrow">DRIVING · TO WORK</div><p class="small">${esc(c.commute_origin)}</p><div style="color:var(--b)">↓</div><p>${esc(c.commute_destination)}</p><p>${link(url,'Open route and live traffic ↗')}</p><div class="tiny muted">Google Maps opens current traffic and driving estimates. No API key required. Live ETA is available in Maps.</div>`;}
function renderYearProgress(){const n=new Date(),start=new Date(n.getFullYear(),0,1),end=new Date(n.getFullYear()+1,0,1),p=(n-start)/(end-start)*100;return `<div class="eta-value">${p.toFixed(1)}%</div><div class="small muted">${n.getFullYear()} complete · Day ${Math.floor((n-start)/86400000)+1}</div><div class="progress-track"><i style="width:${p}%"></i></div>`;}
function solarInstant(text,zone){if(!text)return NaN;const target=Date.parse(text+'Z');let guess=target;for(let i=0;i<3;i++){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess));const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));const wall=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second);guess+=target-wall;}return guess;}
function solarRemaining(w,n=Date.now()){const zone=w.timezone||state.config.timezone;const rises=(w.daily.sunrise||[]).map(t=>solarInstant(t,zone)),sets=(w.daily.sunset||[]).map(t=>solarInstant(t,zone));for(let i=0;i<rises.length;i++){if(n>=rises[i]&&n<sets[i])return {label:'Daylight Remaining',hours:(sets[i]-n)/3600000,until:'Until sunset'};}const next=rises.find(t=>t>n);return {label:'Moonlight Remaining',hours:next?(next-n)/3600000:null,until:'Nighttime until sunrise'};}
function renderDaylight(){const w=state.weather;if(!w)return empty('Set the shared ZIP in Settings → Weather.');const r=solarRemaining(w);return `<div class="eyebrow">${esc(r.label)}</div><div class="eta-value">${r.hours===null?'—':r.hours.toFixed(1)+' hours'}</div><div class="small muted">${esc(r.until)} · ${esc(w.place)}</div>${r.hours===null?'<div class="tiny muted">Refresh weather for the next sunrise.</div>':''}`;}
